head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > M > getOpenPanelListInfo]<br/>Accordion 컴포넌트에서 현재 열려 있는 패널들의 정보를 배열로 반환합니다.",
    "validation" : [
        "getOpenPanelListInfo() 호출 시 현재 열려 있는 패널들의 정보를 객체 배열(Array) 로 반환합니다.",
        "열려 있는 패널이 없으면 빈 배열 ([]) 을 반환합니다.",
        "반환된 객체의 id 속성은 패널의 렌더링 ID (String) 를 갖습니다.",
        "반환된 객체의 org_id 속성은 패널이 컴포넌트 내에서 부여된 ID (String) 를 갖습니다.",
        "반환된 객체의 userID 속성은 패널의 사용자 지정 ID (String) 를 갖습니다.",
        "반환된 객체의 isOpen 속성은 패널의 열림 상태 (Boolean) 를 갖습니다.",
        "반환된 객체의 disabledPanels 속성은 패널의 비활성화 상태 (Boolean) 를 갖습니다.",
        "반환된 객체의 element 속성은 패널의 DOM Element 를 갖습니다.",
        "independentPanel=false 이면 getOpenPanelListInfo() 는 빈 배열 또는 1 개의 패널 정보만 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        independentPanel : con_independentPanel.getText(),
    };

    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* panels1 : 기본 / panels2 : id=myUser2 (userID 검증) / panels3 : disabledPanels=true (닫힘 유지)"', '', 'label1');
    $c.gcm.createLabel('label="* independentPanel=true : 사용자 panelTitle 클릭으로 여러 패널 열림 → 반환 배열에 여러 객체"', '', 'label2');
    $c.gcm.createLabel('label="* independentPanel=false : 빈 배열 또는 1 개 패널 정보만 반환"', '', 'label3');
    $c.gcm.createLabel('label="* 반환 객체 속성 : id(렌더링 ID) → org_id(부여 ID) → userID(사용자 지정) → isOpen → disabledPanels → element(DOM)"', '', 'label4');
    $c.gcm.createLabel('label="* 모든 패널 닫기 후 호출 시 빈 배열 [] 반환"', '', 'label5');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="myUser2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="" disabledPanels="true">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3 (disabled)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// 모두 열기 — openPanel 반복 호출로 다중 패널 열기 시도
scwin.btn_openAll_onclick = function (e) {
    target1.openPanel("panels1");
    target1.openPanel("myUser2");
    target1.openPanel("panels3");
    wf_body_bottom.getObj("scwin").setReturnValue("===== 모두 열기 (openPanel 호출) =====");
};



// 모두 닫기 — closePanel 반복 호출로 빈 배열 [] 반환 검증용
scwin.btn_closeAll_onclick = function (e) {
    target1.closePanel("panels1");
    target1.closePanel("myUser2");
    target1.closePanel("panels3");
    wf_body_bottom.getObj("scwin").setReturnValue("===== 모두 닫기 (closePanel 호출) =====");
};



// getOpenPanelListInfo() 호출 — 현재 열린 패널 정보 배열 출력
scwin.btn_getOpenPanelListInfo_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 호출 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("반환 타입(Array 여부) : " + Array.isArray(openList));
    wf_body_bottom.getObj("scwin").setReturnValue("반환 배열 길이 : " + openList.length);
    if (openList.length === 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("빈 배열 [] 반환");
    } else {
        for (let i = 0; i < openList.length; i++) {
            let p = openList[i];
            wf_body_bottom.getObj("scwin").setReturnValue("------- 열린 패널[" + i + "] -------");
            wf_body_bottom.getObj("scwin").setReturnValue("id : " + p.id);
            wf_body_bottom.getObj("scwin").setReturnValue("org_id : " + p.org_id);
            wf_body_bottom.getObj("scwin").setReturnValue("userID : " + p.userID);
            wf_body_bottom.getObj("scwin").setReturnValue("isOpen : " + p.isOpen);
            wf_body_bottom.getObj("scwin").setReturnValue("disabledPanels : " + p.disabledPanels);
            wf_body_bottom.getObj("scwin").setReturnValue("element.tagName : " + (p.element ? (typeof p.element.getTagName === "function" ? p.element.getTagName() : p.element.tagName) : "null"));
        }
    }
};
